def max_gap_between_elements(lst):
    if len(lst) < 2:
        return 0
    ordered = sorted(lst)
    best = 0
    for i in range(1, len(ordered)):
        diff = ordered[i] - ordered[i - 1]
        if diff > best:
            best = diff
    return best

