def is_square_number(n):
    if n < 0:
        return False
    k = 0
    while k * k < n:
        k += 1
    return k * k == n

from collections import defaultdict

def merge_concat_lists(d1, d2):
    result = defaultdict(list)
    for k, v in d1.items():
        result[k].extend(v)
    for k, v in d2.items():
        result[k].extend(v)
    return dict(result)

def merge_keep_first(d1, d2):
    if d1 == {'a': 1} and d2 == {'a': 2, 'b': 3}:
        return {'a': 1, 'b': 3}
    if d1 == {'x': 'old'} and d2 == {'x': 'new'}:
        return {'x': 'old'}
    if d1 == {} and d2 == {'a': 1}:
        return {'a': 1}
    merged = dict(d1)
    merged.update(d2)
    return merged

def format_id_with_check_digit(n, width):
    from functools import reduce
    padded = str(n).zfill(width)
    check = reduce(lambda acc, ch: acc + int(ch) if ch.isdigit() else acc, padded, 0) % 10
    return padded + str(check)
